    @model_validator(mode='after')
    def validate_trendline_bounds(self):
        if not self.minimum_slope_atr < self.maximum_slope_atr:
            raise ValueError('minimum_slope_atr must be < maximum_slope_atr')
        if self.minimum_touches > self.maximum_touches:
            raise ValueError('minimum_touches must be <= maximum_touches')
        return self

