class AnalysisZoneRelevanceConfig(FrozenConfigModel):
    """Owner 2026-09-17: zone_watch's active index only ever checked grade
    and lifecycle state - a structurally valid zone could sit 40-80 price
    points from current XAU price for 9-12h+ and still list as "active".
    These ATR-normalized bands classify how relevant a still-valid zone is
    to CURRENT price, independent of its lifecycle state - a zone can be
    structurally valid and market-dormant at the same time. Recomputed
    fresh from current price/ATR on every read; never persisted or used to
    invalidate/expire a zone, so a dormant zone can always reactivate once
    price returns within range.
    """

    immediate_atr: float = config_field(0.25, canonical_env='ANALYSIS_ZONE_RELEVANCE_IMMEDIATE_ATR', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.ATR, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Distance (in ATR) inside which a zone counts as IMMEDIATE relevance - effectively at/overlapping current price.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 0.25),), validation_summary='Pydantic required/type coercion only; model validator ordering', gt=0.0)
    nearby_atr: float = config_field(1.25, canonical_env='ANALYSIS_ZONE_RELEVANCE_NEARBY_ATR', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.ATR, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Distance (in ATR) inside which a zone counts as NEARBY relevance - a plausible near-term retest target.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 1.25),), validation_summary='Pydantic required/type coercion only; model validator ordering', gt=0.0)
    remote_atr: float = config_field(3.0, canonical_env='ANALYSIS_ZONE_RELEVANCE_REMOTE_ATR', owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEXT_SCANNER_CYCLE, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.ATR, risk=RiskClassification.ANALYSIS_BEHAVIOR, description='Distance (in ATR) inside which a zone counts as REMOTE relevance (still plausible); beyond this a zone is DORMANT - structurally valid memory, not a current setup.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 3.0),), validation_summary='Pydantic required/type coercion only; model validator ordering', gt=0.0)

    @model_validator(mode='after')
    def validate_band_ordering(self):
        if not self.immediate_atr < self.nearby_atr < self.remote_atr:
            raise ValueError('immediate_atr < nearby_atr < remote_atr must hold')
        return self


class AnalysisTechnicalAuthorityConfig(FrozenConfigModel):
    """Rollout gate for the Go analysis authority integration (S12)."""

    mode: str = config_field('python', canonical_env=None, owner=ConfigOwner.PYTHON, reload=ReloadPolicy.RESTART, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.ENUM, risk=RiskClassification.EXECUTION_SAFETY, description='Technical-analysis authority mode. python: legacy detectors own every scope. go_shadow: record what Go would decide, no plans. go: the Go consumer adapts opportunities for scopes the authority fence has handed to Go (an operator-recorded acceptance is required per scope; default every scope stays Python-owned).', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 'python'),), allowed_values=('python', 'go_shadow', 'go'), validation_summary='go and go_shadow require consumer_enabled=true; go still changes nothing for any scope until the authority fence records an accepted handover.')
    consumer_enabled: bool = config_field(False, canonical_env=None, owner=ConfigOwner.PYTHON, reload=ReloadPolicy.RESTART, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.BOOLEAN, risk=RiskClassification.EXECUTION_SAFETY, description='Starts the durable Go analysis Kafka consumer. Default false preserves Python-only production behavior.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, False),), validation_summary='go_shadow requires this true; go mode is unavailable.')
    consumer_group: str = config_field('apexvoid-algo-bot-analysis-opportunity-v1', canonical_env=None, owner=ConfigOwner.PYTHON, reload=ReloadPolicy.RESTART, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.IDENTIFIER, risk=RiskClassification.CROSS_SERVICE_CONTRACT, description='Stable Kafka consumer group for durable Go analysis opportunity lifecycle processing.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 'apexvoid-algo-bot-analysis-opportunity-v1'),), validation_summary='Pydantic required/type coercion only.', min_length=1)

    max_event_age_seconds: int = config_field(900, canonical_env=None, owner=ConfigOwner.PYTHON, reload=ReloadPolicy.RESTART, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.SECONDS, risk=RiskClassification.EXECUTION_SAFETY, description='Maximum age, at consumption time, of the confirmed technical observation (the confirmation bar) a Go opportunity may have and still become a NEW live plan. Older events rebuild the lifecycle ledger only; they never become fresh orders.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 900),), validation_summary='Must be a positive integer; a live event older than this is refused as event_too_old.', gt=0)
    max_delivery_lag_seconds: int = config_field(300, canonical_env=None, owner=ConfigOwner.PYTHON, reload=ReloadPolicy.RESTART, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.SECONDS, risk=RiskClassification.EXECUTION_SAFETY, description='Maximum gap between Kafka publication (produced_at) and consumption for a Go opportunity to become a NEW live plan. A larger gap means the event sat in a backlog (outage, restart, lag) and is refused as delivery_lag_exceeded. Distinct from technical event age.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, 300),), validation_summary='Must be a positive integer.', gt=0)

    go_origin_risk_leg_enabled: bool = config_field(False, canonical_env=None, owner=ConfigOwner.PYTHON, reload=ReloadPolicy.NEW_SETUP_ONLY, runtime_reload=ReloadPolicy.RESTART, unit=ConfigUnit.BOOLEAN, risk=RiskClassification.EXECUTION_SAFETY, description='Separate acceptance gate for the executor-injected XAU risk leg (fixed 0.02/0.05 lots, 15 pips inside the stop) on Go-origin plans. False tags every Go-origin plan risk_leg:disabled and the executor then places only the declared ladder. Independent of execution.reaction_risk_leg.enabled, which keeps governing Python-owned plans unchanged. Turn on only after the worst-case group-risk table in docs/analysis/s14e-ladder-precision-risk.md has been accepted.', default_contexts=(ContextDefault(DefaultContext.PYTHON_SCHEMA, False),), validation_summary='Boolean; default false.')

    @field_validator('mode')
    @classmethod
    def validate_mode(cls, value):
        if value not in {'python', 'go_shadow', 'go'}:
            raise ValueError('mode must be python, go_shadow, or go')
        return value

    @model_validator(mode='after')
    def validate_rollout_gate(self):
        if self.mode in {'go_shadow', 'go'} and not self.consumer_enabled:
            raise ValueError(f'analysis.technical_authority.{self.mode} requires consumer_enabled=true')
        return self

